source='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(g[r+dr][c+dc] == 3 for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc) != (0,0)):
                centers.append((r,c))
    for r,c in centers:
        row_count = sum(v == 2 for v in g[r])
        col_count = sum(g[i][c] == 2 for i in range(h))
        wall_vertical = col_count > row_count
        # The ray runs perpendicular to the 2-line through the motif.
        coords = ((r,j) for j in range(w)) if wall_vertical else ((i,c) for i in range(h))
        for i,j in coords:
            if g[i][j] == 0:
                g[i][j] = 1
            if g[i][j] == 2 and (i,j) != (r,c):
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        ni,nj=i+di,j+dj
                        if (di,dj) != (0,0) and 0 <= ni < h and 0 <= nj < w:
                            g[ni][nj] = 1
    return g
'''
